    return all((x <= 0) or (env.grid.get(x - 1, y) is None) or (env.grid.get(x - 1, y).type != "ball") for x in range(env.width) for y in range(env.height) for cell in [env.grid.get(x, y)] if cell is not None and cell.type == "door")

def has_door_key(env):
